        m_gaurd_objects.pop_back();
        if (object.second)
            add_object_mesh(*object.first);
    }

    void add_object_mesh(ModelObject& object) {
        for (auto& g : m_gaurd_objects) {
            if (g.first == &object) {
                ++g.second;
                return;
